function drawMonster(m){const y=laneY[m.lane],bob=Math.sin(elapsed*7+m.phase)*4,sc=m.kind==='rex'?1.2:1;ctx.save();ctx.translate(m.x,y+bob);ctx.scale(sc,sc);ctx.shadowColor=m.kind==='rex'?'#ff6656':'#b8e63e';ctx.shadowBlur=m.x<lineX+115?18:5;
 if(m.kind==='zombie'){
  ctx.fillStyle='#82b950';rounded(-24,-29,49,47,15);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#637f36';ctx.fillRect(-18,10,10,15);ctx.fillRect(10,9,10,16);ctx.fillStyle='#b9e57a';ctx.beginPath();ctx.arc(-11,-13,6,0,Math.PI*2);ctx.arc(10,-13,6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#2d3926';ctx.beginPath();ctx.arc(-11,-13,2.5,0,Math.PI*2);ctx.arc(10,-13,2.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#3b4127';rounded(-13,-1,26,10,3);ctx.fill();ctx.fillStyle='#f0edc2';ctx.fillRect(-9,0,6,5);ctx.fillRect(3,0,6,5);ctx.strokeStyle='#a5d363';ctx.lineWidth=7;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-20,-2);ctx.lineTo(-34,4);ctx.moveTo(20,-2);ctx.lineTo(32,-9);ctx.stroke();
 }else{
  ctx.fillStyle=m.kind==='rex'?'#d85c46':'#e28147';ctx.beginPath();ctx.ellipse(0,0,31,20,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.ellipse(19,-20,22,15,-.25,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.moveTo(29,-21);ctx.lineTo(49,-15);ctx.lineTo(33,-9);ctx.fill();ctx.fillStyle='#f7edb4';ctx.beginPath();ctx.arc(24,-25,4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#24281e';ctx.beginPath();ctx.arc(25,-25,1.8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f4dd8a';for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(34+i*3,-12);ctx.lineTo(36+i*3,-6);ctx.lineTo(38+i*3,-13);ctx.fill()}ctx.fillStyle='#bd503c';ctx.beginPath();ctx.moveTo(-21,-12);ctx.lineTo(-34,-29);ctx.lineTo(-27,-3);ctx.fill();ctx.beginPath();ctx.moveTo(-5,-17);ctx.lineTo(-12,-34);ctx.lineTo(3,-18);ctx.fill();ctx.strokeStyle='#713d35';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-12,13);ctx.lineTo(-17,25);ctx.moveTo(13,13);ctx.lineTo(15,25);ctx.stroke();
 }
 ctx.restore();ctx.font='16px sans-serif';ctx.textAlign='center';ctx.fillText(m.kind==='rex'?'🦖':'🧟',m.x,y-39+bob);
}
function drawFX(dt){for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=30*dt;p.life-=dt;ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();if(p.life<=0)particles.splice(i,1)}ctx.globalAlpha=1}
function render(dt){ctx.clearRect(0,0,W,H);if(shake>0){ctx.save();ctx.translate(rnd(-shake,shake),rnd(-shake,shake));shake=Math.max(0,shake-dt*18)}scenery();
 // lane instrument cues
 const colors=['#ffad5c','#d18bff','#66d8eb'],icons=['🥁','🎸','🎺'];for(let i=0;i<3;i++){ctx.fillStyle='#111913cc';rounded(14,laneY[i]-17,54,34,8);ctx.fill();ctx.strokeStyle=colors[i]+'85';ctx.lineWidth=1;rounded(14,laneY[i]-17,54,34,8);ctx.stroke();ctx.font='19px sans-serif';ctx.textAlign='center';ctx.fillText(icons[i],41,laneY[i]+7)}
 monsters.forEach(drawMonster);drawFX(dt);
 if(!active&&!gameOver){ctx.fillStyle='#e7ffd060';ctx.font='700 11px "DM Mono",monospace';ctx.textAlign='center';ctx.fillText('A CIDADE ESTÁ EM SILÊNCIO... POR ENQUANTO.',590,478)}
 if(shake>0)ctx.restore();
}
function spawn(){let lane=Math.floor(Math.random()*3),rex=wave>=3&&Math.random()<Math.min(.24,.08+(wave-3)*.025);monsters.push({lane,x:spawnX,kind:rex?'rex':'zombie',speed:145+wave*13,phase:Math.random()*8});}
function update(dt){if(!active||paused)return;elapsed+=dt;spawnTimer-=dt;if(spawnTimer<=0){spawn();spawnTimer=Math.max(.76,1.42-(wave-1)*.055)+Math.random()*.32}
 for(let i=monsters.length-1;i>=0;i--){let m=monsters[i];m.x-=m.speed*dt;if(m.x<lineX-37){monsters.splice(i,1);loseLife()}}
 const newWave=Math.floor(kills/12)+1;if(newWave!==wave){wave=newWave;ui.wave.textContent=String(wave).padStart(2,'0');notify(`ONDA ${wave} — MAIS RÁPIDO!`);sound(430,.25,'triangle')}
}
function hit(lane){if(!active||paused||gameOver){if(!active&&!gameOver)startGame();return}let candidates=monsters.filter(m=>m.lane===lane);let target=candidates.sort((a,b)=>Math.abs(a.x-lineX)-Math.abs(b.x-lineX))[0];const colors=['#ffad5c','#d18bff','#66d8eb'];if(target&&Math.abs(target.x-lineX)<88){monsters.splice(monsters.indexOf(target),1);combo++;kills++;const perfect=Math.abs(target.x-lineX)<35;let pts=(perfect?150:100)+Math.min(combo*5,100);score+=pts;ui.score.textContent=String(score).padStart(5,'0');ui.combo.innerHTML=`x${combo} <small>🔥</small>`;ui.comboTag.classList.toggle('show',combo>=2);ui.mission.style.width=`${Math.min(100,kills%10*10)}%`;if(score>best){best=score;localStorage.setItem('ritmo-best',best);ui.best.textContent=String(best).padStart(5,'0')}
 for(let i=0;i<18;i++)particles.push({x:target.x,y:laneY[lane],vx:rnd(-130,130),vy:rnd(-160,25),life:rnd(.35,.8),max:.8,r:rnd(2,5),color:colors[lane]});shake=perfect?1.5:0.6;notify(perfect?'PERFEITO! +'+pts:'NO RITMO! +'+pts);sound([175,250,390][lane]*(perfect?1.5:1),.16,['triangle','sawtooth','sine'][lane],.075);if(combo>0&&combo%5===0)notify(`${combo}x COMBO!`)
 }else{combo=0;ui.combo.innerHTML='x0 <small>🔥</small>';ui.comboTag.classList.remove('show');sound(95,.16,'square',.04);document.querySelector('.arena').animate([{filter:'brightness(1)'},{filter:'brightness(1.45)'},{filter:'brightness(1)'}],{duration:220})}}
function loseLife(){lives--;combo=0;ui.combo.innerHTML='x0 <small>🔥</small>';ui.comboTag.classList.remove('show');ui.lives.textContent='♥ '.repeat(Math.max(0,lives)).trim()+(lives?'':'');ui.lives.style.opacity=lives?1:.45;shake=8;notify('A HORDA PASSOU!');sound(72,.3,'sawtooth',.09);if(lives<=0)endGame()}
function notify(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),850)}
function startGame(){if(gameOver){score=0;combo=0;kills=0;wave=1;lives=5;monsters=[];particles=[];ui.score.textContent='00000';ui.combo.innerHTML='x0 <small>🔥</small>';ui.lives.textContent='♥ ♥ ♥ ♥ ♥';ui.lives.style.opacity=1;ui.wave.textContent='01';gameOver=false}active=true;paused=false;spawnTimer=.45;ui.start.classList.add('hidden');ui.pause.classList.add('hidden');ui.status.textContent='A horda está chegando — mantenha o ritmo!';sound(330,.12,'triangle')}
function togglePause(){if(!active||gameOver)return;paused=!paused;ui.pause.classList.toggle('hidden',!paused);ui.pauseTitle.textContent='PAUSA NO SHOW';ui.pauseCopy.textContent='A horda está esperando...';document.getElementById('resumeBtn').textContent='VOLTAR AO PALCO →';}
function endGame(){active=false;gameOver=true;paused=false;ui.pause.classList.remove('hidden');ui.pauseTitle.textContent='FIM DE SHOW';ui.pauseCopy.textContent=`Você marcou ${score} pontos e derrotou ${kills} monstros.`;document.getElementById('resumeBtn').textContent='TENTAR DE NOVO →';ui.status.textContent='A cidade precisa de um bis. Tente novamente!'}
function frame(t){let dt=Math.min(.04,(t-lastTime)/1000||0);lastTime=t;update(dt);render(dt);requestAnimationFrame(frame)}requestAnimationFrame(frame);

