function hit(lane){if(!active||paused||gameOver){if(!active&&!gameOver)startGame();return}let target=monsters.filter(m=>m.lane===lane).sort((a,b)=>Math.abs(a.x-lineX)-Math.abs(b.x-lineX))[0],colors=['#ffad5c','#d18bff','#66d8eb'];if(target&&Math.abs(target.x-lineX)<88){monsters.splice(monsters.indexOf(target),1);combo++;kills++;const perfect=Math.abs(target.x-lineX)<35,pts=(perfect?150:100)+Math.min(combo*5,100);score+=pts;ui.score.textContent=String(score).padStart(5,'0');ui.combo.innerHTML=`x${combo} <small>🔥</small>`;ui.comboTag.classList.toggle('show',combo>=2);ui.mission.style.width=`${Math.min(100,kills%10*10)}%`;if(score>best){best=score;localStorage.setItem('ritmo-best',best);ui.best.textContent=String(best).padStart(5,'0')}for(let i=0;i<18;i++)particles.push({x:target.x,y:laneY[lane],vx:rnd(-130,130),vy:rnd(-160,25),life:rnd(.35,.8),max:.8,r:rnd(2,5),color:colors[lane]});shake=perfect?1.5:.6;notify(perfect?'PERFEITO! +'+pts:'NO RITMO! +'+pts);sound([175,250,390][lane]*(perfect?1.5:1),.16,['triangle','sawtooth','sine'][lane],.075);if(combo>0&&combo%5===0)notify(`${combo}x COMBO!`)}else{combo=0;ui.combo.innerHTML='x0 <small>🔥</small>';ui.comboTag.classList.remove('show');sound(95,.16,'square',.04);document.querySelector('.arena').animate([{filter:'brightness(1)'},{filter:'brightness(1.45)'},{filter:'brightness(1)'}],{duration:220})}}
function loseLife(){lives--;combo=0;ui.combo.innerHTML='x0 <small>🔥</small>';ui.comboTag.classList.remove('show');ui.lives.textContent='♥ '.repeat(Math.max(0,lives)).trim();ui.lives.style.opacity=lives?1:.45;shake=8;notify('A HORDA PASSOU!');sound(72,.3,'sawtooth',.09);if(lives<=0)endGame()}
function notify(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),850)}
function startGame(){if(gameOver){score=0;combo=0;kills=0;wave=1;lives=5;monsters=[];particles=[];ui.score.textContent='00000';ui.combo.innerHTML='x0 <small>🔥</small>';ui.lives.textContent='♥ ♥ ♥ ♥ ♥';ui.lives.style.opacity=1;ui.wave.textContent='01';gameOver=false}active=true;paused=false;spawnTimer=.45;ui.start.classList.add('hidden');ui.pause.classList.add('hidden');ui.status.textContent='A horda está chegando — mantenha o ritmo!';sound(330,.12,'triangle')}
function togglePause(){if(!active||gameOver)return;paused=!paused;ui.pause.classList.toggle('hidden',!paused);ui.pauseTitle.textContent='PAUSA NO SHOW';ui.pauseCopy.textContent='A horda está esperando...';document.getElementById('resumeBtn').textContent='VOLTAR AO PALCO →'}
function endGame(){active=false;gameOver=true;paused=false;ui.pause.classList.remove('hidden');ui.pauseTitle.textContent='FIM DE SHOW';ui.pauseCopy.textContent=`Você marcou ${score} pontos e derrotou ${kills} monstros.`;document.getElementById('resumeBtn').textContent='TENTAR DE NOVO →';ui.status.textContent='A cidade precisa de um bis. Tente novamente!'}
function frame(t){let dt=Math.min(.04,(t-lastTime)/1000||0);lastTime=t;update(dt);render(dt);requestAnimationFrame(frame)}requestAnimationFrame(frame);

