 const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#1c2a1e');g.addColorStop(.58,'#273629');g.addColorStop(1,'#131d19');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
