 ctx.fillStyle='#111b16';for(let i=0;i<8;i++){let x=i*147+((i%2)*18);ctx.beginPath();ctx.moveTo(x,193);ctx.lineTo(x+10,156);ctx.lineTo(x+25,173);ctx.lineTo(x+39,131);ctx.lineTo(x+53,174);ctx.lineTo(x+67,149);ctx.lineTo(x+80,194);ctx.fill()}
 ctx.fillStyle='#202a24';ctx.beginPath();ctx.moveTo(0,208);ctx.lineTo(1000,208);ctx.lineTo(1000,520);ctx.lineTo(0,520);ctx.fill();
 for(let i=0;i<3;i++){let y=laneY[i];ctx.fillStyle=['#e9954930','#a76bd428','#43bcd42b'][i];ctx.beginPath();ctx.moveTo(0,y-33);ctx.lineTo(1000,y-26);ctx.lineTo(1000,y+29);ctx.lineTo(0,y+34);ctx.closePath();ctx.fill();ctx.strokeStyle=['#ffad5c40','#ce87ff40','#61d8e940'][i];ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,y-33);ctx.lineTo(1000,y-26);ctx.moveTo(0,y+34);ctx.lineTo(1000,y+29);ctx.stroke();for(let x=15;x<1000;x+=110){ctx.fillStyle='#d5dfc40b';ctx.fillRect(x,y-1,54,2)}}
 ctx.save();ctx.shadowColor='#d8ff50';ctx.shadowBlur=15;ctx.strokeStyle='#d8ff50';ctx.globalAlpha=.72;ctx.lineWidth=2;ctx.setLineDash([6,7]);ctx.beginPath();ctx.moveTo(lineX,183);ctx.lineTo(lineX,424);ctx.stroke();ctx.restore();
 for(let i=0;i<27;i++){let x=(i*173+31)%1000,y=220+(i*89)%280;ctx.fillStyle=i%2?'#b4d34b18':'#d7e4c315';ctx.save();ctx.translate(x,y);ctx.rotate(i*.7);ctx.beginPath();ctx.ellipse(0,0,7,2.4,0,0,Math.PI*2);ctx.fill();ctx.restore()}
 const bob=active&&!paused?Math.sin(elapsed*8)*2:0;
 ctx.save();ctx.translate(91,356+bob);ctx.fillStyle='#0e1513aa';ctx.beginPath();ctx.ellipse(2,61,72,12,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#242b2a';rounded(-24,4,24,51,10);ctx.fill();rounded(2,4,24,51,10);ctx.fill();ctx.fillStyle='#d9ff55';rounded(-25,48,25,9,4);ctx.fill();rounded(1,48,25,9,4);ctx.fill();ctx.fillStyle='#e7e9d5';rounded(-31,-39,65,56,18);ctx.fill();ctx.fillStyle='#8b5636';ctx.beginPath();ctx.arc(1,-52,21,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d9b48c';ctx.beginPath();ctx.arc(1,-50,17,0,Math.PI*2);ctx.fill();ctx.fillStyle='#283027';ctx.beginPath();ctx.arc(2,-58,20,Math.PI,Math.PI*2);ctx.lineTo(21,-54);ctx.lineTo(-18,-54);ctx.fill();ctx.fillStyle='#252a24';ctx.fillRect(-7,-51,4,3);ctx.fillRect(7,-51,4,3);
