const combat=await ev("({score:document.querySelector('#score').textContent,combo:document.querySelector('#combo').textContent,wave:document.querySelector('#wave').textContent,lives:document.querySelector('#lives').textContent})");
await ev("document.querySelector('#pauseBtn').click();document.querySelector('#resumeBtn').click();true");
await new Promise(r=>setTimeout(r,19000));
const over=await ev("({title:document.querySelector('#pauseTitle').textContent,copy:document.querySelector('#pauseCopy').textContent,disabled:document.querySelector('#pauseBtn').disabled})");
await ev("document.querySelector('#resumeBtn').click();true");
const restarted=await ev("({score:document.querySelector('#score').textContent,lives:document.querySelector('#lives').textContent,overlayHidden:document.querySelector('#pauseOverlay').classList.contains('hidden'),pauseIcon:document.querySelector('#pauseBtn').textContent,pauseDisabled:document.querySelector('#pauseBtn').disabled})");
console.log(JSON.stringify({combat,over,restarted},null,2));ws.close();
